M2_from_full_iri_narrow.from:
const term = Namespace.fromTermIRI(iri);
if (term) {
  return `${term.namespace.prefix}__${term.localName}`;
}
return iri;

M2_from_full_iri_narrow.to:
const m = iri.match(
  /https:\/\/exocortex\.my\/ontology\/([a-z]+)#(.+)$/,
);
if (m) {
  return `${m[1]}__${m[2]}`;
}
return iri;

M3_rank_property_narrow.from:
const parsed = Namespace.fromPropertyKey(enumClass);
if (!parsed) return null;
return `${parsed.namespace.prefix}__${parsed.localName}_rank`;

M3_rank_property_narrow.to:
const m = enumClass.match(/^([a-z]+)__(.+)$/);
if (!m) return null;
return `${m[1]}__${m[2]}_rank`;
